def solve(stream, registers):
    # Read 4 bits from the stream and store each in a separate register
    for i in range(4):
        bit = stream.next_bit()
        registers.set(i, bit)

    # Reconstruct the list from the registers
    result = []
    for i in range(4):
        result.append(registers.get(i))

    return result

