def kth_alternating_permutation(n: int, k: int) -> List[int]:
    """ Given two integers n and k, return the k-th alternating permutation of the first n positive integers. """
    if n == 0:
        return []

    # Count of odds and evens in the set {1, ..., n}
    num_odds = (n + 1) // 2
    num_evens = n // 2

    # memo[o][e][last_parity] = number of ways to complete the permutation
    # last_parity: 0 for even, 1 for odd, 2 for start
    memo = {} 

    def count_ways(o, e, last_parity):
        state = (o, e, last_parity)
        if state in memo: return memo[state]
        if o == 0 and e == 0:
            return 1

        res = 0
        # If last was even (0) or start (2), we can pick an odd
        if last_parity != 1 and o > 0:
            res += o * count_ways(o - 1, e, 1)
        # If last was odd (1) or start (2), we can pick an even
        if last_parity != 0 and e > 0:
            res += e * count_ways(o, e - 1, 0)

        memo[state] = res
        return res

    total_count = count_ways(num_odds, num_evens, 2)
    if k > total_count:
        return []

    result = []
    odds_available = sorted([i for i in range(1, n + 1) if i % 2 != 0])
    evens_available = sorted([i for i in range(1, n + 1) if i % 2 == 0])

    curr_o, curr_e = num_odds, num_evens
    last_parity = 2
    current_k = k

    for i in range(n):
        # Try candidates in increasing order to maintain lexicographical order
        # Candidates are either odds or evens depending on parity of previous element
        candidates = []
        if last_parity != 1:
            for val in odds_available:
                candidates.append((val, 1))
        if last_parity != 0:
            for val in evens_available:
                candidates.append((val, 0))

        candidates.sort()

        found = False
        for val, parity in candidates:
            # Calculate how many permutations start with this specific value
            # Note: since we fix the specific value, we just need the count of ways 
            # to arrange the remaining numbers of the correct parity.
            if parity == 1:
                ways = count_ways(curr_o - 1, curr_e, 1)
            else:
                ways = count_ways(curr_o, curr_e - 1, 0)

            if current_k <= ways:
                result.append(val)
                if parity == 1:
                    odds_available.remove(val)
                    curr_o -= 1
                else:
                    evens_available.remove(val)
                    curr_e -= 1
                last_parity = parity
                found = True
                break
            else:
                current_k -= ways

        if not found:
            return []

    return result

