            next_value = current_value + value
            if next_diff not in new_dp or next_value > new_dp[next_diff]:
                new_dp[next_diff] = next_value
        dp = new_dp

    # Return the max taste for diff 0, provided at least one fruit was used
    if 0 in dp and dp[0] > 0:
        return dp[0]
    else:
        return -1

